<script setup lang="ts">
import { t as uiText } from '@/locales'

import { partnerError as requestError } from "@/utils/partnerError";
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router';
import { ElMessage, ElMessageBox } from 'element-plus';
import { useUserStore } from '@/stores/user';
import { previewUnitCost, researchAction, type ProductResearchDetail, type UnitCostRow, type UnitCostSheet } from '@/api/modules/productResearch';

const props=defineProps<{detail:ProductResearchDetail}>();
const emit=defineEmits<{updated:[ProductResearchDetail]}>();
const user=useUserStore(),busy=ref(false),calculating=ref(false),dirty=ref(false),error=ref(''),selected=ref('draft');
const groups=[{key:'material',name:'材料成本'},{key:'process',name:'加工成本'},{key:'tooling',name:'模具摊销'},{key:'tool_transport',name:'模具运输摊销'},{key:'development',name:'开发费用'},{key:'freight_sea',name:'成品海运'},{key:'freight_air',name:'成品空运'}];
function empty():UnitCostSheet{return {title:'单件成本估算',currency:'CNY',displayCurrency:'',exchangeRate:null,exchangeRateDate:null,taxBasis:'source',rows:[],references:[],bomId:null,routeId:null,reason:'',notes:''};}
const sheet=reactive<UnitCostSheet>(empty()),calculated=ref<UnitCostSheet|null>(null);
const versions=computed(()=>((props.detail.workflow.unitCostVersions||[]) as UnitCostSheet[]));
const canWrite=computed(()=>user.hasPermission('finance:write')&&props.detail.canWrite&&!['archived'].includes(props.detail.status)&&!['frozen','abandoned'].includes(props.detail.lockStatus||''));
const editable=computed(()=>canWrite.value&&selected.value==='draft');
const routes=computed(()=>(props.detail.bomRoutes||[]).filter(r=>r.bomId===sheet.bomId));
const directPurchase=computed(()=>(props.detail.workflow.plan as Record<string,any>)?.method==='direct'&&(props.detail.workflow.plan as Record<string,any>)?.needsMold===false);
const quotes=computed(()=>props.detail.events.filter(e=>e.kind==='quote'));
const boms=computed(()=>props.detail.materials.filter(m=>m.type==='bom'));
const totals=computed(()=>calculated.value?.totals||{});
const missing=computed(()=>calculated.value?.missing||[]),warnings=computed(()=>calculated.value?.warnings||[]);
let hydrating=false,timer:ReturnType<typeof setTimeout>|undefined,generation=0;
const copy=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
function assign(value:UnitCostSheet){hydrating=true;Object.keys(sheet).forEach(k=>delete (sheet as any)[k]);Object.assign(sheet,empty(),copy(value));calculated.value=copy(value);dirty.value=false;hydrating=false;}
watch(()=>props.detail.productId,()=>{selected.value='draft';assign((props.detail.workflow.unitCostDraft as UnitCostSheet)||empty());if(!sheet.totals)void calculate();},{immediate:true});
async function calculate(){const current=++generation;calculating.value=true;try{const result=await previewUnitCost(props.detail.productId,copy(sheet));if(current===generation){calculated.value=result;error.value='';}}catch(e){if(current===generation){calculated.value=null;error.value=e instanceof Error?e.message:'核算失败，请重试';}}finally{if(current===generation)calculating.value=false;}}
watch(sheet,()=>{if(hydrating||!editable.value)return;dirty.value=true;calculated.value=null;clearTimeout(timer);timer=setTimeout(()=>void calculate(),450);},{deep:true,flush:'sync'});
onBeforeUnmount(()=>{clearTimeout(timer);generation++;});
function groupRows(category:string){return sheet.rows.filter(r=>r.category===category);}
function computedRow(id:string){return calculated.value?.rows.find(r=>r.id===id);}
function money(value:number|null|undefined){return value==null?'待补':Number(value).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4});}
function convert(value:number|null|undefined){return !sheet.displayCurrency||value==null||sheet.exchangeRate==null?null:Number(value)*Number(sheet.exchangeRate);}
function addRow(category:string){sheet.rows.push({id:crypto.randomUUID(),category,name:'',description:'',mode:'unit',unitPrice:null,quantity:null,lossPct:null,allocationQty:null,taxIncluded:null,taxRate:null,remark:''});}
async function removeRow(row:UnitCostRow){try{await ElMessageBox.confirm(uiText('删除“{value0}”这条草稿明细？',{value0:(row.name||'未命名费用')}),uiText('删除明细'));sheet.rows.splice(sheet.rows.indexOf(row),1);}catch{}}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();}catch(e){if(e!=='cancel'&&e!=='close'){error.value=requestError(e);ElMessage.error(error.value);}}finally{busy.value=false;}}
async function save(confirm=false){await run(async()=>{clearTimeout(timer);if(confirm)await ElMessageBox.confirm(uiText('确认本次核算采用的BOM路线或供方报价，以及税率和汇率依据？确认后通过新版本修订。'),uiText('确认单件成本'));const d=await researchAction(props.detail.productId,confirm?'unit_cost_confirm':'unit_cost_save',props.detail.workflow.version,copy(sheet));emit('updated',d);dirty.value=false;if(confirm){const list=(d.workflow.unitCostVersions||[]) as UnitCostSheet[];const last=list[list.length-1];selected.value=String(last.id);assign(last);}else assign(d.workflow.unitCostDraft as UnitCostSheet);ElMessage.success(confirm?uiText('成本版本已确认并保存采用依据'):uiText('成本草稿已保存'));});}
async function choose(value:string){if(dirty.value){try{await ElMessageBox.confirm(uiText('当前核算有未保存修改，切换后放弃这些修改？'),uiText('未保存草稿'));}catch{return;}}selected.value=value;assign(value==='draft'?((props.detail.workflow.unitCostDraft as UnitCostSheet)||empty()):versions.value.find(v=>String(v.id)===value)!);if(value==='draft'&&!sheet.totals)void calculate();}
async function create(){if(dirty.value||props.detail.workflow.unitCostDraft){try{await ElMessageBox.confirm(uiText('当前已有核算草稿；新建后保存会替换它。确认重新填写？'),uiText('新建核算'));}catch{return;}}selected.value='draft';assign(empty());groups.filter(g=>!g.key.startsWith('freight')).forEach(g=>addRow(g.key));}
async function copyVersion(){if(props.detail.workflow.unitCostDraft){try{await ElMessageBox.confirm(uiText('已有服务器草稿，复制版本将准备替换该草稿，保存后生效。'),uiText('复制核算版本'));}catch{return;}}const value=copy(sheet);delete value.id;delete value.status;delete value.bomCostSnapshotId;delete value.voidReason;delete value.confirmedAt;delete value.confirmedBy;value.reason='';selected.value='draft';assign(value);dirty.value=true;void calculate();}
async function removeDraft(){await run(async()=>{await ElMessageBox.confirm(uiText('删除服务器上的成本草稿？已确认版本仍保留。'),uiText('删除成本草稿'));const d=await researchAction(props.detail.productId,'unit_cost_delete',props.detail.workflow.version,{});emit('updated',d);selected.value='draft';assign(empty());});}
async function voidVersion(){await run(async()=>{const reason=await ElMessageBox.prompt(uiText('填写作废原因，历史计算和依据继续保留。'),uiText('作废成本版本'),{inputValidator:v=>!!v?.trim()||uiText('请填写原因')});const d=await researchAction(props.detail.productId,'unit_cost_void',props.detail.workflow.version,{id:sheet.id,reason:reason.value});emit('updated',d);assign(((d.workflow.unitCostVersions||[]) as UnitCostSheet[]).find(v=>v.id===sheet.id)!);});}
function bomChanged(){sheet.routeId=null;sheet.references=sheet.references.filter(r=>r.type!=='bom');if(sheet.bomId)sheet.references.push({type:'bom',id:sheet.bomId});}
async function importBom(){await run(async()=>{if(!sheet.bomId||!sheet.routeId)throw Error('请先选择具体BOM及工艺路线');if(dirty.value||props.detail.workflow.unitCostDraft)await ElMessageBox.confirm(uiText('从选定BOM读取物料、数量和已有价格，替换成本草稿；未明确费用继续留空。'),uiText('从BOM带入'));const d=await researchAction(props.detail.productId,'unit_cost_from_bom',props.detail.workflow.version,{bomId:sheet.bomId,routeId:sheet.routeId,replaceDraft:true});emit('updated',d);selected.value='draft';assign(d.workflow.unitCostDraft as UnitCostSheet);});}
async function leave(){if(busy.value)return false;if(dirty.value){try{await ElMessageBox.confirm(uiText('单件成本尚未保存，离开页面？'),uiText('未保存输入'));}catch{return false;}}return true;}
onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);
defineExpose({canLeave:leave});
</script>

<template>
 <section class="unit-cost-sheet" :aria-label='uiText("单件成本核算")'>
  <div class="sheet-toolbar"><strong>{{ uiText("单件成本核算") }}</strong><el-select :model-value="selected" :aria-label='uiText("核算版本")' @change="choose"><el-option :label='uiText("当前草稿")' value="draft"/><el-option v-for="v in versions" :key="v.id" :value="String(v.id)" :label="uiText('C{value0} · {value1}{value2}',{value0:(v.id),value1:(v.title),value2:(v.voidReason?' · 已作废':'')})"/></el-select><template v-if="canWrite"><el-button @click="create">{{ uiText("新建核算") }}</el-button><el-button v-if="selected!=='draft'" @click="copyVersion">{{ uiText("复制为新版本") }}</el-button><el-button v-if="editable" :loading="busy" type="primary" @click="save(false)">{{ uiText("保存成本草稿") }}</el-button><el-button v-if="editable" :disabled="busy" @click="save(true)">{{ uiText("确认成本版本") }}</el-button><el-button v-if="editable&&detail.workflow.unitCostDraft" type="danger" @click="removeDraft">{{ uiText("删除草稿") }}</el-button><el-button v-if="selected!=='draft'&&!sheet.voidReason" type="danger" @click="voidVersion">{{ uiText("作废版本") }}</el-button></template><el-button :loading="calculating" @click="calculate">{{ uiText("重新核算") }}</el-button></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <div v-if="sheet.voidReason" class="notice">{{ uiText("已作废：") }}{{sheet.voidReason}}</div>
  <p v-if="!canWrite" class="muted">{{ uiText("当前可查看核算。价格、税率、汇率及成本确认由具有财务维护权限的人员办理。") }}</p>
  <el-form :disabled="!editable||busy" class="sheet-settings" label-position="left" @submit.prevent>
   <el-select v-model="sheet.currency" clearable filterable allow-create default-first-option :aria-label='uiText("核算币种")' :placeholder='uiText("币种待确认")'><el-option v-for="currency in ['CNY','MXN','USD','EUR']" :key="currency" :value="currency" :label="currency"/></el-select>
   <el-input v-model="sheet.title" :aria-label='uiText("核算名称")' :placeholder='uiText("核算名称")'/><el-select v-model="sheet.taxBasis" :aria-label='uiText("核算税额口径")'><el-option :label='uiText("原表估算口径（待核对）")' value="source"/><el-option :label='uiText("统一未税成本")' value="net"/><el-option :label='uiText("统一含税成本")' value="gross"/></el-select><el-select v-model="sheet.displayCurrency" :aria-label='uiText("换算币种")'><el-option value="" :label='uiText("不换算")'/><el-option v-for="c in ['MXN','USD','CNY','EUR']" :key="c" :value="c" :label="uiText('换算为 {value0}',{value0:(c)})"/></el-select><template v-if="sheet.displayCurrency"><label>1 {{sheet.currency}} =</label><el-input-number v-model="sheet.exchangeRate" :controls="false" :min="0" :aria-label='uiText("换算汇率")' :placeholder='uiText("汇率待补")'/><span>{{sheet.displayCurrency||uiText('换算价')}}</span><el-date-picker v-model="sheet.exchangeRateDate" value-format="YYYY-MM-DD" :placeholder='uiText("汇率依据日期")' :aria-label='uiText("汇率依据日期")'/></template>
   <el-select v-if="directPurchase||sheet.basisType==='supplier_quote'" v-model="sheet.basisType" :placeholder='uiText("成本依据（默认BOM）")' :aria-label='uiText("核算依据类型")'><el-option value="bom" :label='uiText("BOM与工艺路线")'/><el-option v-if="directPurchase" value="supplier_quote" :label='uiText("采购成品供方报价")'/></el-select>
   <template v-if="sheet.basisType==='supplier_quote'"><el-select v-model="sheet.quoteEventId" filterable :placeholder='uiText("选择已有供方报价")' :aria-label='uiText("核算采用供方报价")'><el-option v-for="q in quotes" :key="q.eventId" :value="q.eventId" :label="`${q.data.supplierName} · ${q.data.amount} ${q.data.currency}／${q.data.unit}`"/></el-select><el-input v-model="sheet.quoteUnitNote" type="textarea" autosize :placeholder='uiText("核对报价单位、税额和单件换算方式")' :aria-label='uiText("报价单件换算说明")'/></template>
   <template v-else><el-select v-model="sheet.bomId" clearable filterable :placeholder='uiText("采用BOM（草稿可空）")' :aria-label='uiText("核算采用BOM")' @change="bomChanged"><el-option v-for="b in boms" :key="b.id" :value="b.id" :label="`${b.name} · ${b.versionNo}`"/></el-select><el-select v-model="sheet.routeId" clearable :placeholder='uiText("采用工艺路线")' :aria-label='uiText("核算采用路线")'><el-option v-for="r in routes" :key="r.routeId" :value="r.routeId" :label="r.name||uiText('路线 {value0}',{value0:(r.routeId)})"/></el-select><el-button @click="importBom">{{ uiText("从BOM带入明细") }}</el-button></template>
  </el-form>
  <p class="muted basis-note">{{sheet.taxBasis==='source'?uiText('当前合计沿用原始估算口径，含税状态未统一，不能作为已确认成本。'):uiText('按选定税额口径核算，各行需要明确税率；不发生的费用填写0并说明。')}} <span v-if="calculating">{{ uiText("正在计算…") }}</span><span v-else-if="dirty">{{ uiText("有未保存修改") }}</span></p>
  <p v-if="'sourceOutputQty' in sheet" class="muted">{{ uiText("来源 BOM 基准产量：") }}{{sheet.sourceOutputQty??uiText('待确认')}}{{ uiText("。非单件基准的原用量仅作来源依据；请核对单位及单件用量，不将批量用量直接当成单件成本。") }}</p>
  <div class="cost-table-wrap"><table class="cost-table"><colgroup><col class="group-col"/><col class="name-col"/><col/><col class="money-col"/><col class="money-col"/><col class="tax-col"/><col class="remark-col"/><col class="action-col"/></colgroup><thead><tr><th>{{ uiText("费用类型") }}</th><th>{{ uiText("费用项目") }}</th><th>{{ uiText("费用说明／计算依据") }}</th><th>{{ uiText("单价／") }}{{sheet.currency}}</th><th>{{ uiText("单价／") }}{{sheet.displayCurrency||uiText('换算价')}}</th><th>{{ uiText("原价含税") }}</th><th>{{ uiText("备注") }}</th><th><span class="sr-only">{{ uiText("操作") }}</span></th></tr></thead>
   <tbody v-for="group in groups" :key="group.key"><tr v-for="(r,index) in groupRows(group.key)" :key="r.id"><td v-if="index===0" :rowspan="groupRows(group.key).length" class="group-cell">{{group.name}}<el-button v-if="editable" link type="primary" @click="addRow(group.key)">{{ uiText("＋新增") }}</el-button></td><td data-label="费用项目"><el-input v-if="editable" v-model="r.name" :aria-label='uiText("费用项目")' :placeholder='uiText("费用项目")'/><span v-else>{{r.name}}</span><small v-if="r.estimated">{{ uiText("预估") }}</small></td><td data-label="计算依据"><template v-if="editable"><el-input v-model="r.description" type="textarea" autosize :aria-label='uiText("费用说明")' :placeholder='uiText("填写材料、规格、计算和报价依据")'/><div class="formula"><el-select v-model="r.mode" :aria-label='uiText("计算方式")'><el-option :label='uiText("直接填单件")' value="unit"/><el-option :label='uiText("单价×用量")' value="usage"/><el-option :label='uiText("总额÷数量")' value="divide"/></el-select><template v-if="r.mode!=='unit'"><el-input-number v-model="r.unitPrice" :controls="false" :min="0" :placeholder="r.mode==='divide'?uiText('总额'):uiText('原料单价')" :aria-label='uiText("计算单价或总额")'/><span>{{r.mode==='divide'?'÷':'×'}}</span><el-input-number v-if="r.mode==='divide'" v-model="r.allocationQty" :controls="false" :min="0" :placeholder='uiText("分摊数量")' :aria-label='uiText("分摊数量")'/><template v-else><el-input-number v-model="r.quantity" :controls="false" :min="0" :placeholder='uiText("用量")' :aria-label='uiText("材料用量")'/><el-input-number v-model="r.lossPct" :controls="false" :min="0" :max="100" :placeholder='uiText("损耗%")' :aria-label='uiText("材料损耗率")'/></template></template></div></template><template v-else><div class="full-text">{{r.description}}</div><small v-if="r.mode==='divide'">{{r.unitPrice}} ÷ {{r.allocationQty}}</small><small v-if="r.mode==='usage'">{{r.unitPrice}} × {{r.quantity}}{{ uiText("，损耗 ") }}{{r.lossPct}}%</small></template></td><td :data-label="sheet.currency ? `${sheet.currency} 单件成本` : '单件成本（币种待确认）'" class="numeric"><el-input-number v-if="editable&&r.mode==='unit'" v-model="r.unitPrice" :controls="false" :min="0" :aria-label='uiText("单件金额")' :placeholder='uiText("待补")'/><span v-else>{{money(computedRow(r.id)?.unitCost)}}</span><small v-if="editable&&r.mode==='unit'&&sheet.taxBasis!=='source'">{{ uiText("核算 ") }}{{money(computedRow(r.id)?.unitCost)}}</small></td><td :data-label="`${sheet.displayCurrency||'换算价'} 换算单价`" class="numeric">{{sheet.displayCurrency?money(computedRow(r.id)?.displayCost):'—'}}</td><td data-label="含税及税率"><template v-if="editable"><el-select v-model="r.taxIncluded" clearable :aria-label='uiText("原价是否含税")' :placeholder='uiText("待定")'><el-option :label='uiText("是")' :value="true"/><el-option :label='uiText("否")' :value="false"/></el-select><el-input-number v-model="r.taxRate" :controls="false" :min="0" :max="100" :placeholder='uiText("税率%")' :aria-label='uiText("税率百分比")'/></template><template v-else>{{r.taxIncluded==null?uiText('待定'):r.taxIncluded?uiText('是'):uiText('否')}}<small>{{ uiText("税率 ") }}{{r.taxRate??uiText('待补')}}%</small></template></td><td data-label="备注"><template v-if="editable"><el-input v-model="r.remark" type="textarea" autosize :aria-label='uiText("成本备注")' :placeholder='uiText("备注")'/><el-input v-if="r.warning" v-model="r.warning" type="textarea" autosize :aria-label='uiText("待核对事项")'/></template><span v-else class="full-text">{{r.remark}}</span><small v-if="r.warning" class="warning">{{ uiText("待核对：") }}{{r.warning}}</small><small v-if="r.sourceCell">{{ uiText("来源：") }}{{r.sourceCell}}</small></td><td class="row-action"><el-button v-if="editable" type="danger" link :aria-label="uiText('删除{value0}',{value0:(r.name||'费用明细')})" @click="removeRow(r)">{{ uiText("删") }}</el-button></td></tr><tr v-if="!groupRows(group.key).length" class="empty-group"><td>{{group.name}}</td><td colspan="7"><span class="muted">{{ uiText("未填写") }}</span><el-button v-if="editable" link type="primary" @click="addRow(group.key)">{{ uiText("＋新增明细") }}</el-button></td></tr><tr v-if="group.key==='process'" class="subtotal"><td colspan="3">{{ uiText("材料＋加工小计") }}</td><td class="numeric">{{money(totals.manufacturing)}}</td><td class="numeric">{{sheet.displayCurrency?money(convert(totals.manufacturing)):'—'}}</td><td colspan="3"></td></tr><tr v-if="group.key==='development'" class="grand-total"><td colspan="3">{{ uiText("单件总成本（成品运输前）") }}</td><td class="numeric">{{money(totals.base)}}</td><td class="numeric">{{sheet.displayCurrency?money(convert(totals.base)):'—'}}</td><td colspan="3">{{sheet.taxBasis==='source'?uiText('原表估算'):uiText('统一税额口径')}}</td></tr><tr v-if="group.key.startsWith('freight')" class="subtotal"><td colspan="3">{{ uiText("含") }}{{group.key==='freight_sea'?uiText('海运'):uiText('空运')}}{{ uiText("合计") }}</td><td class="numeric">{{money(totals[group.key])}}</td><td class="numeric">{{sheet.displayCurrency?money(convert(totals[group.key])):'—'}}</td><td colspan="3">{{group.key==='freight_sea'?uiText('海运'):uiText('空运')}}{{ uiText("方案单独计算") }}</td></tr></tbody></table></div>
  <details v-if="missing.length||warnings.length" class="cost-gaps"><summary>{{ uiText("待补 ") }}{{missing.length}}{{ uiText(" 项 · 待核对 ") }}{{warnings.length}}{{ uiText(" 项") }}</summary><p v-for="(text,index) in [...missing,...warnings]" :key="index">{{text}}</p></details>
  <el-input v-if="editable" v-model="sheet.reason" :placeholder='uiText("修订已确认成本时填写原因")' :aria-label='uiText("成本修订原因")'/><el-input v-if="editable" v-model="sheet.notes" type="textarea" autosize :placeholder='uiText("核算范围、假设、供应商及资料依据")' :aria-label='uiText("核算说明")'/><p v-else class="full-text">{{sheet.notes}}<br/>{{sheet.confirmedBy}} {{sheet.confirmedAt}}</p>
 </section>
